108	                /*approval_policy*/ None,
109	                /*approvals_reviewer*/ None,
110	                /*permission_profile*/ None,
111	                /*windows_sandbox_level*/ None,
112	                /*model*/ None,
113	                /*effort*/ None,
114	                /*summary*/ None,
115	                Some(service_tier.clone()),
116	                /*collaboration_mode*/ None,
117	                /*personality*/ None,
118	            )));
119	        self.app_event_tx
120	            .send(AppEvent::PersistServiceTierSelection { service_tier });
121	    }
122	
123	    fn model_supports_service_tier(&self, model: &str, service_tier: &str) -> bool {
124	        self.model_catalog
125	            .try_list_models()
126	            .ok()
127	            .and_then(|models| {
128	                models
129	                    .into_iter()
130	                    .find(|preset| preset.model == model)
131	                    .map(|preset| {
132	                        preset
133	                            .service_tiers
134	                            .iter()
135	                            .any(|tier| tier.id == service_tier)
136	                    })
137	            })
138	            .unwrap_or(false)
139	    }
140	
141	    fn current_model_fast_service_tier(&self) -> Option<ServiceTierCommand> {
142	        self.current_model_service_tier_commands()
143	            .into_iter()
144	            .find(|tier| tier.name.eq_ignore_ascii_case(SPEED_TIER_FAST))
145	    }
146	}
